package br.com.onda;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;

@androidx.media3.common.util.UnstableApi
public class DownloadCenterActivity extends Activity {
 private final Handler handler=new Handler(Looper.getMainLooper());private final ArrayList<DownloadHistory.Entry> shown=new ArrayList<>();private int filter;private boolean wasActive;private String snapshot="";private TextView summary;private Rows adapter;private final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();
 private final Runnable tick=new Runnable(){public void run(){refresh();handler.postDelayed(this,1000);}};
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,16),Ui.dp(this,12)+i.getSystemWindowInsetTop(),Ui.dp(this,16),Ui.dp(this,12)+i.getSystemWindowInsetBottom());return i;});setContentView(root);
  LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.addView(Ui.button(this,"‹",v->finish()),new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));TextView title=Ui.text(this,"Central de downloads",20,Ui.TEXT);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));bar.addView(Ui.menuButton(this,"Menu da central",v->Ui.menu(this,v,new String[]{"Novo download","Arquivos do Onda","Conversor local","Escolher pasta do Onda",OndaFolders.enabled(this)?"Pedir local a cada download":"Usar pasta do Onda","Cancelar operação","Limpar histórico finalizado"},new String[]{"Novo download","Arquivos do Onda","Conversor local","Escolher pasta do Onda","Alterar local dos próximos downloads","Cancelar operação","Limpar registros, sem apagar arquivos"},new Runnable[]{()->startActivity(new Intent(this,DownloadsActivity.class)),()->startActivity(new Intent(this,OndaFilesActivity.class)),()->startActivity(new Intent(this,LocalConverterActivity.class)),this::chooseFolder,this::toggleFolder,this::cancel,this::clear})),new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));root.addView(bar);
  Spinner tabs=new Spinner(this);tabs.setContentDescription("Filtrar histórico de downloads");ArrayAdapter<String> options=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Todos","Em andamento","Concluídos","Falhas e interrupções"});tabs.setAdapter(options);root.addView(tabs,new LinearLayout.LayoutParams(-1,Ui.dp(this,48)));tabs.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int position,long id){filter=position;snapshot="";refresh();}});
  summary=Ui.text(this,"",13,Ui.MUTED);root.addView(summary);ListView list=new ListView(this);list.setDivider(null);adapter=new Rows();list.setAdapter(adapter);list.setOnItemClickListener((p,v,index,id)->actions(shown.get(index)));root.addView(list,new LinearLayout.LayoutParams(-1,0,1));TextView note=Ui.text(this,"Histórico local a partir desta versão, até 200 arquivos. Tentar novamente consulta o link e pede um novo destino; não retoma bytes após encerrar a operação.",12,Ui.MUTED);root.addView(note);
 }
 private void refresh(){if(summary==null||adapter==null)return;if(wasActive&&!MediaDownloadService.activeDownload)DownloadHistory.settle(this,"interrupted","A operação anterior foi encerrada. Tente novamente para reanalisar o link.");wasActive=MediaDownloadService.activeDownload;String data=getSharedPreferences(DownloadHistory.PREF,0).getString("data","");if(data.equals(snapshot))return;snapshot=data;List<DownloadHistory.Entry> all=DownloadHistory.read(this);shown.clear();int active=0,done=0,failed=0;for(DownloadHistory.Entry e:all){if(e.active())active++;else if(e.state.equals("done"))done++;else failed++;if(filter==0||filter==1&&e.active()||filter==2&&e.state.equals("done")||filter==3&&!e.active()&&!e.state.equals("done"))shown.add(e);}summary.setText(all.isEmpty()?"Nenhum arquivo registrado ainda.":active+" na fila/em andamento • "+done+" concluídos • "+failed+" com falha/interrupção");adapter.notifyDataSetChanged();}
 private void actions(DownloadHistory.Entry e){ArrayList<String> names=new ArrayList<>();ArrayList<Runnable> actions=new ArrayList<>();if(e.state.equals("done")&&!e.uri.isEmpty()){names.add("Abrir arquivo");actions.add(()->open(e));}if(e.retryable()){names.add("Tentar novamente");actions.add(()->startActivity(new Intent(this,DownloadsActivity.class).putExtra("retry_link",e.source)));}if(e.active()){names.add("Cancelar operação");actions.add(this::cancel);}names.add("Copiar detalhes");actions.add(()->{String detail=e.title+"\n"+DownloadHistory.label(e.state)+"\n"+e.detail;((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Download Onda",detail));Toast.makeText(this,"Detalhes copiados",Toast.LENGTH_SHORT).show();});new AlertDialog.Builder(this).setTitle(e.title).setItems(names.toArray(new String[0]),(d,n)->actions.get(n).run()).setNegativeButton("Fechar",null).show();}
 private void open(DownloadHistory.Entry e){try{Uri uri=Uri.parse(e.uri);if(!"content".equals(uri.getScheme())&&!"file".equals(uri.getScheme()))throw new IllegalArgumentException();Intent i=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,MediaDownloadService.mime(e.format)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION).setClass(this,e.format.equals("mp4")?VideoActivity.class:MainActivity.class);startActivity(i);}catch(Exception error){new AlertDialog.Builder(this).setMessage("Não foi possível abrir. Confira se o arquivo existe e se o acesso à pasta continua permitido.").setPositiveButton("OK",null).show();}}
 private void cancel(){if(MediaDownloadService.activeDownload)new AlertDialog.Builder(this).setTitle("Cancelar operação?").setMessage("Arquivos já concluídos serão mantidos.").setNegativeButton("Voltar",null).setPositiveButton("Cancelar operação",(d,w)->startService(new Intent(this,MediaDownloadService.class).setAction("cancel"))).show();else Toast.makeText(this,"Nenhuma operação em andamento",Toast.LENGTH_SHORT).show();}
 private void clear(){new AlertDialog.Builder(this).setTitle("Limpar histórico finalizado?").setMessage("Remove os registros concluídos, falhos e cancelados. Os arquivos salvos permanecem na pasta escolhida.").setNegativeButton("Voltar",null).setPositiveButton("Limpar histórico",(d,w)->{DownloadHistory.clearFinished(this);snapshot="";refresh();}).show();}
 private final class Rows extends BaseAdapter {
  public int getCount(){return shown.size();}public Object getItem(int p){return shown.get(p);}public long getItemId(int p){return p;}
  public View getView(int p,View reusable,android.view.ViewGroup parent){LinearLayout box;if(reusable instanceof LinearLayout)box=(LinearLayout)reusable;else{box=new LinearLayout(DownloadCenterActivity.this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(Ui.dp(DownloadCenterActivity.this,12),Ui.dp(DownloadCenterActivity.this,12),Ui.dp(DownloadCenterActivity.this,12),Ui.dp(DownloadCenterActivity.this,12));box.addView(Ui.text(DownloadCenterActivity.this,"",16,Ui.TEXT));box.addView(Ui.text(DownloadCenterActivity.this,"",12,Ui.CYAN));box.addView(new ProgressBar(DownloadCenterActivity.this,null,android.R.attr.progressBarStyleHorizontal),new LinearLayout.LayoutParams(-1,Ui.dp(DownloadCenterActivity.this,18)));box.addView(Ui.text(DownloadCenterActivity.this,"",12,Ui.MUTED));Ui.card(box,false);}DownloadHistory.Entry e=shown.get(p);((TextView)box.getChildAt(0)).setText(e.title);((TextView)box.getChildAt(1)).setText(DownloadHistory.label(e.state)+" • "+e.format.toUpperCase(Locale.ROOT)+" • "+android.text.format.DateFormat.format("dd/MM HH:mm",e.time));ProgressBar progress=(ProgressBar)box.getChildAt(2);progress.setVisibility(e.state.equals("running")?View.VISIBLE:View.GONE);progress.setIndeterminate(e.expected<=0);progress.setMax(100);if(e.expected>0)progress.setProgress((int)Math.min(100,e.bytes*100/e.expected));String bytes=e.bytes>0?"\nTrecho transferido: "+android.text.format.Formatter.formatShortFileSize(DownloadCenterActivity.this,e.bytes)+(e.expected>0?" de "+android.text.format.Formatter.formatShortFileSize(DownloadCenterActivity.this,e.expected):""):"";((TextView)box.getChildAt(3)).setText(e.detail+bytes);return box;}
 }
 private void chooseFolder(){try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),710);}catch(Exception e){Toast.makeText(this,"Seletor de pastas indisponível",Toast.LENGTH_LONG).show();}}
 private void toggleFolder(){if(getSharedPreferences(OndaFolders.PREF,0).getString("tree","").isEmpty()){chooseFolder();return;}boolean enabled=OndaFolders.enabled(this);getSharedPreferences(OndaFolders.PREF,0).edit().putBoolean("enabled",!enabled).apply();Toast.makeText(this,enabled?"O Android pedirá o local de cada download":"Próximos downloads em Onda/Áudios ou Onda/Vídeos",Toast.LENGTH_LONG).show();}
 @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=710||result!=RESULT_OK||data==null||data.getData()==null)return;Uri tree=data.getData();try{getContentResolver().takePersistableUriPermission(tree,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(Exception ignored){}worker.execute(()->{String message;try{OndaFolders.configure(this,tree);message="Pasta configurada: Onda/Áudios e Onda/Vídeos. Novos downloads usarão essas pastas.";}catch(Exception e){message="Não foi possível configurar. Selecione uma pasta gravável pelo Android.";}String resultMessage=message;runOnUiThread(()->{if(!isDestroyed())new AlertDialog.Builder(this).setTitle("Pasta do Onda").setMessage(resultMessage).setPositiveButton("OK",null).show();});});}
 @Override public void onDestroy(){worker.shutdownNow();super.onDestroy();}
 @Override public void onStart(){super.onStart();wasActive=MediaDownloadService.activeDownload;if(!wasActive)DownloadHistory.settle(this,"interrupted","A operação anterior foi encerrada. Tente novamente para reanalisar o link.");snapshot="\u0000";handler.post(tick);}@Override public void onStop(){handler.removeCallbacks(tick);super.onStop();}
}
